-    fn internal_return_bonds(&mut self, policy: &Policy, proposal: &Proposal) -> Promise {
+    const REFUND_OPEN: u8 = 0;
+    const REFUND_IN_FLIGHT: u8 = 1;
+    const REFUND_SETTLED: u8 = 2;
+    const REFUND_FAILED: u8 = 3;
+    const GAS_FOR_REFUND_CALLBACK: Gas = Gas::from_tgas(20);
+
+    fn proposal_bond_key(proposal_id: u64) -> Vec<u8> {
+        let mut key = b"proposal_bond:".to_vec();
+        key.extend_from_slice(&proposal_id.to_le_bytes());
+        key
+    }
+
+    fn refund_state_key(proposal_id: u64) -> Vec<u8> {
+        let mut key = b"proposal_refund:".to_vec();
+        key.extend_from_slice(&proposal_id.to_le_bytes());
+        key
+    }
+
+    fn read_refund_state(proposal_id: u64) -> Option<(u8, u64, u128)> {
+        let value = env::storage_read(&Self::refund_state_key(proposal_id))?;
+        if value.len() != 25 {
+            env::panic_str("ERR_INVALID_REFUND_STATE");
+        }
+        let mut attempt = [0u8; 8];
+        attempt.copy_from_slice(&value[1..9]);
+        let mut bond = [0u8; 16];
+        bond.copy_from_slice(&value[9..]);
+        Some((
+            value[0],
+            u64::from_le_bytes(attempt),
+            u128::from_le_bytes(bond),
+        ))
+    }
+
+    fn write_refund_state(proposal_id: u64, status: u8, attempt: u64, bond: u128) {
+        let mut value = Vec::with_capacity(25);
+        value.push(status);
+        value.extend_from_slice(&attempt.to_le_bytes());
+        value.extend_from_slice(&bond.to_le_bytes());
+        env::storage_write(&Self::refund_state_key(proposal_id), &value);
+    }
+
+    fn legacy_bond_provenance_key(proposal_id: u64) -> Vec<u8> {
+        let mut key = b"legacy_proposal_bond_provenance:".to_vec();
+        key.extend_from_slice(&proposal_id.to_le_bytes());
+        key
+    }
+
+    fn proposal_bond_amount(proposal_id: u64) -> Option<u128> {
+        let value = env::storage_read(&Self::proposal_bond_key(proposal_id))?;
+        if value.len() != 16 {
+            env::panic_str("ERR_INVALID_PROPOSAL_BOND");
+        }
+        Some(u128::from_le_bytes(value.try_into().unwrap()))
+    }
+
+    fn internal_return_proposal_bond(
+        &mut self,
+        proposal_id: u64,
+        proposal: &Proposal,
+    ) -> PromiseOrValue<()> {
+        let Some(amount) = Self::proposal_bond_amount(proposal_id) else {
+            log!(
+                "Refusing refund for proposal {} without a trusted legacy principal",
+                proposal_id
+            );
+            return PromiseOrValue::Value(());
+        };
+        if amount == 0 {
+            return PromiseOrValue::Value(());
+        }
+        let (status, attempt, recorded_bond) =
+            Self::read_refund_state(proposal_id).unwrap_or((Self::REFUND_OPEN, 0, amount));
+        let bond = if recorded_bond == 0 {
+            amount
+        } else {
+            recorded_bond
+        };
+        if bond != amount {
+            env::panic_str("ERR_PROPOSAL_BOND_MISMATCH");
+        }
+        match status {
+            Self::REFUND_SETTLED | Self::REFUND_IN_FLIGHT => return PromiseOrValue::Value(()),
+            Self::REFUND_OPEN | Self::REFUND_FAILED => {}
+            _ => env::panic_str("ERR_INVALID_REFUND_STATE"),
+        }
+        let next_attempt = attempt.checked_add(1).expect("ERR_REFUND_ATTEMPT_OVERFLOW");
+        Self::write_refund_state(proposal_id, Self::REFUND_IN_FLIGHT, next_attempt, bond);
+        Promise::new(proposal.proposer.clone())
+            .transfer(NearToken::from_yoctonear(bond))
+            .then(
+                Self::ext(env::current_account_id())
+                    .with_static_gas(Self::GAS_FOR_REFUND_CALLBACK)
+                    .on_refund_callback(proposal_id, next_attempt),
+            )
+            .into()
+    }
+
+    fn internal_return_bonds(
+        &mut self,
+        proposal_id: u64,
+        policy: &Policy,
+        proposal: &Proposal,
+    ) -> PromiseOrValue<()> {
         if let ProposalKind::BountyDone { .. } = &proposal.kind {
